                        break;
                    }
                }
            }
        }
    }

    /**
     * Randomly select the weather for this step.
     */
    private void updateWeather()
    {
        Random rand = Randomizer.getRandom();
        if (rand.nextDouble() <= 0.33) {
            weather = "Foggy";
        } else if (rand.nextDouble() <= 0.33) {
            weather = "Rainy";
        } else {
            weather = "Sunny";
        }
    }

