 */
public class Lion extends Animal
{
    // Characteristics shared by all lions (class variables).
    private static final int BREEDING_AGE = 10;
    private static final int MAX_AGE = 225;
    private static final double BREEDING_PROBABILITY = 0.10;
    private static final int MAX_LITTER_SIZE = 5;
    private static final Random rand = Randomizer.getRandom();
    private static final int FOOD_VALUE = 20;
    private static final int DEFAULT_FOOD_LEVEL = 275;

    // Individual characteristics (instance fields).
    private int foodLevel;

    /**
     * Create a Lion. A Lion can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     *
     * @param randomAge If true, the Lion will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Lion(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        if (randomAge) {
            age = rand.nextInt(MAX_AGE);
            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
        } else {
            foodLevel = 40;
        }
    }

    @Override protected int getMaxAge()                      { return MAX_AGE; }
    @Override protected int getBreedingAge()                 { return BREEDING_AGE; }
    @Override protected double getBreedingProbability()      { return BREEDING_PROBABILITY; }
    @Override protected int getMaxLitterSize()               { return MAX_LITTER_SIZE; }
    @Override public    int foodValue()                      { return FOOD_VALUE; }

    /**
     * This is what the Lion does most of the time: it hunts for prey.
     * If the weather is foggy, it stops moving.
     * @param newLions A list to return newly born lions.
     * @param step The current step.
     * @param weather The current weather.
     */
    public void act(List<Entity> newLions, int step, String weather)
    {
        incrementAge();
        incrementHunger();
        updateBurnStatus(weather);

        if (isAlive()) {
            giveBirth(newLions);
            Location newLocation;
            if (weather.equals("Foggy")) {
                newLocation = null;
            } else {
                newLocation = findFood();
            }
            if (newLocation == null) {
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            if (step % 4 != 0) {
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    setDead();
                }
            }
        }
    }

    /**
     * Make this lion more hungry. This could result in the lion's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if (foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Look for deer, cat, owl, or mouse adjacent to the current location.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        Field<Entity> field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Entity animal = field.getObjectAt(where);
            if (animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if (deer.isAlive()) {
                    deer.setDead();
                    foodLevel += deer.foodValue();
                    return where;
                }
            } else if (animal instanceof Cat) {
                Cat cat = (Cat) animal;
                if (cat.isAlive()) {
                    cat.setDead();
                    foodLevel += cat.foodValue();
                    return where;
                }
            } else if (animal instanceof Owl) {
                Owl owl = (Owl) animal;
                if (owl.isAlive()) {
                    owl.setDead();
                    foodLevel += owl.foodValue();
                    return where;
                }
            } else if (animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if (mouse.isAlive()) {
                    mouse.setDead();
                    foodLevel += mouse.foodValue();
                    return where;
                }
            }
        }
        return null;
    }

    /**
     * Check whether or not this lion is to give birth at this step.
     * Requires an opposite-gender lion within a 2-step radius.
     * @param newLions A list to return newly born lions.
     */
    private void giveBirth(List<Entity> newLions)
    {
        boolean breedingPair = false;
        Field<Entity> field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation(), 2);
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Entity animal = field.getObjectAt(where);
            if (animal instanceof Lion) {
                Lion lion = (Lion) animal;
                if (lion.getGender() != getGender()) {
                    breedingPair = true;
                    break;
                }
            }
        }

        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for (int b = 0; b < births && free.size() > 0 && breedingPair; b++) {
            Location loc = free.remove(0);
            newLions.add(new Lion(false, field, loc));
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.Random;

/**
 * A simple model of a Grass.
 * Deers age, move, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Grass extends Plant
{
    // Characteristics shared by all Grass (class variables).

    // The age to which a Grass can live.
    private static final int MAX_SIZE = 50;
    // The maximum grow rate.
    private static final int MAX_GROW_RATE = 20;
    // The likelihood of grass get steppe fire.
    private static final double STEPPE_FIRE_PROBABILITY = 0.02;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    // Individual characteristics (instance fields).

    // The Grass's age.
    private int size;
    // The Grass's steppe fire status
    private boolean steppeFired;

    /**
     * Create a new Grass. A Grass may be created with size
     * 50 or with a random size.
     * 
     * @param randomSize If true, the Grass will have a random size.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(boolean randomSize, Field field, Location location)
    {
        super(field, location);

        if(randomSize) {
            size = rand.nextInt(MAX_SIZE);
        }
        else {
            size = 50;
        }
        steppeFired = false;
    }

    /**
     * This is what the Grass does most of the time - it grows 
     * around. Sometimes it will breed or die of steppeFire. If
     * the grass catches fire, it will also burn the unit adjacent to it 
     * @param step The current step
     * @param weather The current weather.
     */
    public void act(List<Entity> newEntities, int step, String weather)
    {
        if(isAlive()) {
            if("Rainy".equals(weather)) {
                incrementSize();
                steppeFired = false;
            }
            else {
                getSteppeFire();
                if (steppeFire() && getLocation() != null) {                
                    Field<Entity> field = getField();
                    List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
                    Iterator<Location> it = adjacent.iterator();
                    while(it.hasNext()) {
                        Location where = it.next();
                        Entity creature = field.getObjectAt(where);
                        if(creature instanceof Grass) {
                            Grass grass = (Grass) creature;
                            grass.getSteppeFire();                        
                        }
                        if(creature instanceof Animal) {
                            Animal animal = (Animal) creature;
                            animal.burn();                        
                        }
                    }

                    decrementSize();                
                }
            }
        }
    }

    /**
     * Increase the size.
     */
    private void incrementSize()
    {
        size = size + rand.nextInt(MAX_GROW_RATE)+20;
        if(size > MAX_SIZE) {
            size = MAX_SIZE;
        }
    }

    /**
     * Decrease the size.
     */
    public void decrementSize()
    {
        size = size -1;
        if(size == 0) {
            setDead();
        }
    }

    /**
     * Grass can become steppe fire.
     */
    private void getSteppeFire()
    {
        if(rand.nextDouble() <= STEPPE_FIRE_PROBABILITY) {
            steppeFired = true;
        }        
    }

    /**
     * Return steppe fire status.
     * @return true if the grass become steppe fire, false otherwise.
     */
    public boolean steppeFire()
    {
        return steppeFired;
    }

    /**
     * Return size status.
     * @return size The current size of the grass.
     */
    public int getSize()
    {
        return size;
    }

}
